-- El juego de caracteres se fija SIEMPRE: el cliente `mysql` lo toma del entorno y en un
-- contenedor sin locale eso es latin1, que convierte cada tilde en mojibake sin dar error.
SET NAMES utf8mb4;
-- Fotos de puntos de interés (poi-images.js)
UPDATE points_of_interest SET image_url = 'Img/poi/cabo-cope.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: J.Alberto, CC BY-SA 4.0)' WHERE slug = 'cabo-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_blanca_2.JPG', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Ingegneriadell´elizia, CC BY 3.0)' WHERE slug = 'cala-blanca' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/calabardina.jpg', source = 'Región de Murcia Digital (CARM) - Águilas, Yacimientos; Wikimedia Commons (foto: Rietje Swart, CC BY-SA 2.0). La pedanía queda 554 m FUERA del límite oficial del espacio protegido: entra como puerta de entrada por carretera, que es la función que cumple, y no como un valor de dentro. Distancia medida contra el `parque.geojson` que sirve la app.' WHERE slug = 'calabardina' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica_de_la_Torre_de_Cope_y_el_Golfo_de_Mazarr%C3%B3n.jpg', source = 'OpenStreetMap contributors (ODbL); tradición oral recogida en fuentes de turismo regional (episodio del incendio pendiente de contrastar con fuente documental primaria); Wikimedia Commons (foto: José Alberto Giménez, CC BY-SA 4.0)' WHERE slug = 'ermita-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Ensenada_de_la_Fuente.jpg', source = 'Wikipedia - "Cabo Cope"; descubriendomurcia.com; tradición oral recogida en fuentes de turismo regional (nombre popular pendiente de confirmar con fuente documental primaria); Wikimedia Commons (foto: Jose Ignacio Martinez Navarro, CC BY-SA 3.0 es)' WHERE slug = 'fuente-piratas' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/lomo-bas.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 ES)' WHERE slug = 'lomo-bas' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/playa-calnegre.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Mueca, CC BY-SA 4.0)' WHERE slug = 'playa-calnegre' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope%2C_desde_la_playa_del_Charco.JPG?width=1280', source = 'Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021); OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'playa-charco' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope%2C_Punta_del_Cerro_de_la_Cruz_o_de_las_Cabricas.JPG?width=1280', source = 'OpenStreetMap contributors (ODbL). SIN FOTO a propósito desde la auditoría del 2026-08-15: la que servía era «Puntas de Calnegre, desde Piedras Negras.JPG», cuyo propio nombre dice que retrata Puntas de Calnegre —otro POI de este mismo espacio, a 10,6 km— y no este saliente; Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 es)' WHERE slug = 'punta-cabricas' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/puntas-calnegre.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Pau lopezca, CC BY-SA 3.0 ES); Región de Murcia Digital (CARM)' WHERE slug = 'puntas-calnegre' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'Img/poi/torre-cope.jpg', source = 'OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Jose Lorca, dominio público); Región de Murcia Digital (CARM)' WHERE slug = 'torre-cope' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
UPDATE points_of_interest SET image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope_-_WLE_Spain_2015.jpg', source = 'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa junto al saladar y la Playa de la Galera; las coordenadas exactas de cada yacimiento no están publicadas. Wikimedia Commons (foto: Raul, CC BY 2.0)' WHERE slug = 'yacimientos-cope-galera' AND park_id = (SELECT id FROM parks WHERE slug = 'cabo-cope-puntas-calnegre');
